PREFIX = 'CIS_TfrmThermostatDamperGroups.TfrmDamperGroups.'


def extract(exe: bytes, mapping: bytes):
    if hashlib.sha256(exe).hexdigest() != EXE_SHA256 or hashlib.sha256(mapping).hexdigest() != MAP_SHA256:
        raise ValueError('Original source byte pins differ')
    image, walker = _Image(exe, mapping), None
    walker = _Walker(image)
    spans, listings = {}, {}
    for name, pin in PINS.items():
        start, end = int(pin['start'], 16), int(pin['end'], 16)
        if name != 'CIS_Error.CISError:damper-overload' and image.by_name.get(name) != start:
            raise ValueError('Original method identity differs: ' + name)
        if next(address for address in image.starts if address > start) != end:
            raise ValueError('Original method boundary differs: ' + name)
        raw = image.pe.get_data(start - image.base, end - start)
        if hashlib.sha256(raw).hexdigest() != pin['sha256']:
            raise ValueError('Original method body differs: ' + name)
        spans[name] = dict(pin)
        if name != 'CIS_Error.CISError:damper-overload':
            listings[name] = walker.listing(name)[0]
    checks = {}
    def require(name, condition):
        if not condition:
            raise ValueError('Static damper source relationship differs: ' + name)
        checks[name] = True
    def calls(name):
        return [int(op, 16) for _a, mnemonic, op, _note in listings[name]
                if mnemonic == 'call' and re.fullmatch(r'0x[0-9a-f]+', op)]
    def operands(name):
        return [op for _a, _m, op, _note in listings[name]]
    def vmt(class_name, offset):
        return walker.dword(image.by_name[class_name] + 0x58 + offset)
    show = calls(PREFIX + 'FormShow')
    require('formshow_setup_is_first_direct_call', show[0] == image.by_name[PREFIX + 'SetupFlashComponents'])
    require('formshow_four_direct_zone_callbacks', show.count(image.by_name[PREFIX + 'cmbGroupChange']) == 4)
    require('formshow_relay_initialise_is_last_direct_call', show[-1] == image.by_name['CIS_TfrmThermostatExternalRelays.TfrmThermostatExternalRelays.Initialise'])
    require('checkbox_checked_vmt_target', vmt('CIS_TFlashCheckBox..TFlashCheckBox', 0xec) == image.by_name['StdCtrls.TCustomCheckBox.GetChecked'])
    require('checkbox_setchecked_vmt_target', vmt('CIS_TFlashCheckBox..TFlashCheckBox', 0xf0) == image.by_name['StdCtrls.TCustomCheckBox.SetChecked'])
    require('checkbox_change_vmt_target', vmt('CIS_TFlashCheckBox..TFlashCheckBox', 0xf8) == image.by_name['CIS_TFlashCheckBox.TFlashCheckBox.Change'])
    require('tracked_root_element_vmt_target', vmt('CIS_Handles..TFlashTrackedHandle', 0x1c) == image.by_name['CIS_Handles.TFlashTrackedHandle.GetRootElement'])
    require('object_reference_getflashobject_vmt_target', vmt('CIS_TObjectReferenceAttribute..TObjectReferenceAttribute', 0xa4) == image.by_name['CIS_TObjectReferenceAttribute.TObjectReferenceAttribute.GetFlashObject'])
    require('group_update_enable_vmt_target', vmt('CIS_TFlashCxGroupComboBox..TFlashCxGroupComboBox', 0x510) == image.by_name['CIS_TFlashCxGroupComboBox.TFlashCxGroupComboBox.UpdateEnableState'])
    require('controller_constructs_tracked_handle', image.by_name['CIS_Handles.TFlashTrackedHandle.Create'] in calls('CIS_Handles.TFlashExpressionController.Create'))
    require('group_constructor_constructs_expression_controller', image.by_name['CIS_Handles.TFlashExpressionController.Create'] in calls('CIS_TFlashCxComboBox.TFlashCxComboBox.Create'))
    click = calls(PREFIX + 'chbEnableDamperModulationClick')
    require('click_uses_actual_error_overload', click == [0x7d9d00])
    require('click_error_number_7323', 'edx, 0x1c9b' in operands(PREFIX + 'chbEnableDamperModulationClick'))
    require('checkbox_state_suppression_guard', 'byte ptr [ebx + 0x270], 0' in operands('StdCtrls.TCustomCheckBox.SetState'))
    require('checkbox_setup_suppression_flag_on', 'byte ptr [eax + 0x270], 1' in operands('CIS_TFlashCheckBox.TFlashCheckBox.ActiveStateChanged'))
    require('checkbox_change_boolean_writer', image.by_name['CIS_Handles.TFlashBooleanController.SetAsBoolean'] in calls('CIS_TFlashCheckBox.TFlashCheckBox.Change'))
    update = calls('CIS_TThermostat.TPlantControlService.UpdateDamperGroups')
    require('zone_update_reads_installed_zones_four_times', update.count(image.by_name['CIS_TThermostat.TCBusParameters.GetInstalledZones']) == 4)
    require('zone_update_first_free_lookup_four_times', update.count(image.by_name['CIS_TCommonCBus.TCBusGroupManager.GetNextAvailableAddress']) == 4)
    require('zone_update_unused_getter_four_times', update.count(image.by_name['CIS_TThermostat.TPlantControlService.GetUnusedGroup']) == 4)
    require('first_free_count_256_guard', 'eax, 0x100' in operands('CIS_TCommonCBus.TCBusGroupManager.GetNextAvailableAddress'))
    require('maximum_address_reservation_getter', image.by_name['CIS_TCommonCBus.TCBUSApplication.GetHasReservedGroupAddress255'] in calls('CIS_TCommonCBus.TCBusGroupManager.GetMaximumPossibleAddress'))
    require('reserved_address255_always_true', 'byte ptr [ebp - 5], 1' in operands('CIS_TCommonCBus.TCBUSApplication.GetHasReservedGroupAddress255'))
    require('first_free_maximum254', 'dword ptr [ebp - 8], 0xfe' in operands('CIS_TCommonCBus.TCBusGroupManager.GetMaximumPossibleAddress'))
    require('unused_group_address255', 'edx, 0xff' in operands('CIS_TThermostat.TPlantControlService.GetUnusedGroup'))
    raw, controls = dfm_properties(image, 'TFRMDAMPERGROUPS')
    declared = {}
    for zone in range(1, 5):
        control = controls['cmbZone' + str(zone) + 'Group']
        props = control['properties']
        require('zone' + str(zone) + '_change_binding', props['Properties.OnChange'] == 'cmbGroupChange')
        require('zone' + str(zone) + '_warning_initially_hidden', controls['Image' + str(zone)]['properties']['Visible'] is False)
        declared['zone' + str(zone)] = {'class': control['class'], 'change': props['Properties.OnChange'],
            'controller_update': props['FlashController.UpdateMode'],
            'list_controller_update': props['FlashListController.UpdateMode']}
    require('checkbox_click_binding', controls['chbEnableDamperModulation']['properties']['OnClick'] == 'chbEnableDamperModulationClick')
    return {'format': 'cbus-thermostat-damper-controls-source-v1',
        'original_inputs': {'EXE': {'sha256': EXE_SHA256, 'bytes': len(exe)}, 'MAP': {'sha256': MAP_SHA256, 'bytes': len(mapping)}},
        'method_spans': spans, 'method_count': len(spans), 'checks': checks, 'check_count': len(checks),
        'declarations': declared, 'binding_count': 5,
        'dfm': {'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw)},
        'facts': {'initial_cache': [None] * 4, 'cache_provenance': 'fresh ordinary model allocation and initial AfterLoad only',
            'cache_offsets_by_zone': ['0x168', '0x160', '0x164', '0x16c'],
            'first_free_address_maximum': 254, 'reserved_unused_address': 255,
            'installed_zone_bits': [2, 4, 8, 16], 'installed_zone_field': 'InstalledZones',
            'separate_plant_zone_field': 'InternalPlantZones',
            'installed_update': 'restore cache for nil/255; find generated name if stillnil/255; create at firstfree iff currentnil and retainedmaster enum0',
            'absent_update': 'cache current non255 only when cache nil; select create-enabled unused255',
            'group_callback': 'nil/nonGroup total noop;255 hides warning only; non255 caches current model getter independently of bound controller',
            'warning_internal_relay': 'TSA5/TSB5 exact object identity among five relay references; master/slave is not tested',
            'modulation_click': {'code': 7323, 'context': 'WHITE', 'model_assignment': False, 'result_consumed': False},
            'installed_setter': 'five Boolean writes zone0..4; unchanged values skip notification; explicit notification intents only',
            'formshow_order': ['SetupFlashComponents', 'cmbGroupChange:1', 'cmbGroupChange:2', 'cmbGroupChange:3', 'cmbGroupChange:4', 'InstallHandleAfterShow', 'ExternalRelays.Initialise']},
        'limits': ['Static byte reads only; no original/native/framework/hardware execution',
            'Closed database network owned profile; no UI rendering, native alert or implicit host dispatch',
            'Complete InstalledZones subscriber inventory/multiplicity and quick-zone queued dispatch remain open',
            'Application migration and template lifecycle not implemented',
            'Group capacity/ambiguous generated-name manager-order cases refuse in the bounded native profile'],
        'original_instructions_executed': False, 'hardware_executed': False, 'workflow_acceptance': False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--exe', required=True, type=Path)
    parser.add_argument('--map', required=True, type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--check', type=Path)
    args = parser.parse_args()
    value = extract(args.exe.read_bytes(), args.map.read_bytes())
    if args.check is not None and json.loads(args.check.read_text()) != value:
        raise SystemExit('Damper source fixture differs')
    if args.output is not None:
        args.output.write_text(json.dumps(value, sort_keys=True, indent=2) + '\n')
    print(json.dumps({'method_count': value['method_count'], 'check_count': value['check_count'],
                      'binding_count': value['binding_count'], 'check': args.check is not None}))


if __name__ == '__main__':
    main()
